            for sym in symbols:
                if sym['st_info']['type'] == 'STT_FUNC' and sym['st_value'] <= addr:
                    offset = addr - sym['st_value']
                    if offset < best_offset and offset < sym['st_size']:
                        best = sym
                        best_offset = offset
            if best:
                print(f'0x{addr:x} -> {best.name}+0x{best_offset:x}')
            else:
                # Try without size check
                for sym in symbols:
                    if sym['st_info']['type'] == 'STT_FUNC' and sym['st_value'] <= addr:
                        offset = addr - sym['st_value']
                        if offset < best_offset:
                            best = sym
                            best_offset = offset
                if best:
                    print(f'0x{addr:x} -> {best.name}+0x{best_offset:x} (approx)')
                else:
                    print(f'0x{addr:x} -> ???')
    else:
        print('No .symtab section')
