                name = sym.name
                if name.startswith('__CortexA53') or name.startswith('\$'):
                    continue
                offset = addr - sym['st_value']
                if offset < best_offset:
                    best = sym
                    best_offset = offset
        if best:
            print(f'0x{addr:x} -> {best.name}+0x{best_offset:x} (size=0x{best[\"st_size\"]:x}, val=0x{best[\"st_value\"]:x})')
