from elftools.elf.elffile import ELFFile

# For the SGen worker addresses, let's look for functions that contain these addresses (within their size)
addresses = [0x2f4b20, 0x2f4c84]

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    symtab = elf.get_section_by_name('.symtab')
    symbols = list(symtab.iter_symbols())

    # List all symbols near these addresses
    for addr in addresses:
        print(f'\\n=== 0x{addr:x} ===')
        candidates = []
        for sym in symbols:
            if sym['st_info']['type'] == 'STT_FUNC':
                start = sym['st_value']
                end = start + sym['st_size']
                if start <= addr < end:
                    candidates.append((sym.name, start, sym['st_size'], addr - start))
        if candidates:
            for name, start, size, offset in candidates:
                print(f'  MATCH: {name} (0x{start:x}, size=0x{size:x}, offset=+0x{offset:x})')
        else:
            # Show nearest
            near = [(sym.name, sym['st_value'], sym['st_size']) for sym in symbols 
                    if sym['st_info']['type'] == 'STT_FUNC' and abs(sym['st_value'] - addr) < 0x200
                    and not sym.name.startswith('__')]
            near.sort(key=lambda x: abs(x[1] - addr))
            for name, val, size in near[:5]:
                print(f'  NEAR: {name} @ 0x{val:x} size=0x{size:x} (diff={addr-val:+d})')
" 2>&1", "description": "Find exact symbols for SGen addresses"}

