from elftools.elf.elffile import ELFFile

addresses = [0x2f4b20, 0x2f4c84]

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)

    # Try DWARF info for line information
    dwarf = elf.get_dwarf_info()

    for CU in dwarf.iter_CUs():
        line_prog = dwarf.line_program_for_CU(CU)
        if line_prog is None:
            continue

        entries = line_prog.get_entries()
        prev_state = None
        for entry in entries:
            state = entry.state
            if state is None:
                continue
            for addr in addresses:
                if prev_state and prev_state.address <= addr < state.address:
                    file_entry = line_prog['file_entry'][prev_state.file - 1]
                    dir_index = file_entry['dir_index']
                    if dir_index > 0:
                        directory = line_prog['include_directory'][dir_index - 1]
                    else:
                        directory = b'.'
                    fname = file_entry.name
                    if isinstance(fname, bytes):
                        fname = fname.decode('utf-8', errors='replace')
                    if isinstance(directory, bytes):
                        directory = directory.decode('utf-8', errors='replace')
                    print(f'0x{addr:x} -> {directory}/{fname}:{prev_state.line}')
            prev_state = state
" 2>&1

